"""Read-only diagnostics after campaign stop: no CAD/mesh generation and no solver."""
from common_e10 import *
from protocol_core import front_parent_datum
from scipy.sparse import coo_matrix
from scipy.sparse.csgraph import connected_components

def main():
 protect();assert (R/'17_reproducibility/CAMPAIGN_STOP.json').exists();sid='C02-V1-S355-AW';folder=R/'06_M1_meshes'/sid;m=np.load(folder/'mesh.npz');a=np.load(folder/'QUADRATIC_GEOMETRY_AUDIT.npz');xx=m['xyz'];tet=m['tet10'];quality=m['quality'];minJ=a['min_sampled_J'];samples=a['Jacobian_samples'];bad=np.flatnonzero((minJ<=0)|(quality<.02));answer=[];ind=[]
 gradients=np.array([[-1.,-1.,-1.],[1.,0,0],[0,1.,0],[0,0,1.]]);edgepairs=[(0,1),(1,2),(2,0),(0,3),(1,3),(2,3)];perm=[0,1,2,3,4,5,6,7,9,8]
 checkids=np.unique(np.r_[bad,np.linspace(0,len(tet)-1,512,dtype=int)])
 for e in checkids:
  coords=xx[tet[e,perm]];dets=[];linear_dets=[];linear=coords.copy();linear[4:]=np.array([(coords[i]+coords[j])/2 for i,j in edgepairs])
  for bary in samples:
   derivative=np.empty((10,3))
   for i in range(4):derivative[i]=(4*bary[i]-1)*gradients[i]
   for k,(i,j) in enumerate(edgepairs):derivative[4+k]=4*(bary[i]*gradients[j]+bary[j]*gradients[i])
   dets.append(float(np.linalg.det(coords.T@derivative)));linear_dets.append(float(np.linalg.det(linear.T@derivative)))
  difference=abs(min(dets)-minJ[e]);assert difference<1e-10;ind.append(dict(element_index=int(e),Gmsh_element_tag=int(m['element_tags'][e]),max_minJ_disagreement_mm3=float(difference),minJ_mm3=min(dets)))
  if e in bad:
   center=coords[:4].mean(0);distport=min(center[0]-xx[:,0].min(),xx[:,0].max()-center[0]);distY=min(center[1]-xx[:,1].min(),xx[:,1].max()-center[1]);movement=np.linalg.norm(coords[4:]-linear[4:],axis=1);worst=int(np.argmin(dets));answer.append(dict(source_id=sid,level='M1',element_index=int(e),Gmsh_element_tag=int(m['element_tags'][e]),X_mm=float(center[0]),Y_mm=float(center[1]),Z_mm=float(center[2]),distance_Xport_mm=float(distport),distance_Yedge_mm=float(distY),minSICN=float(quality[e]),minJ_mm3=min(dets),negative_samples=int((np.array(dets)<0).sum()),worst_barycentric=samples[worst].tolist(),linear_midside_same_element_minJ_mm3=min(linear_dets),maximum_midside_curvature_displacement_mm=float(movement.max()),diagnostic='Counterfactual midside-linearization of same element only; not a remeshed or solved candidate'))
 table(R/'08_mesh_quality/INVALID_ELEMENT_COORDINATES.csv',answer);table(R/'08_mesh_quality/INDEPENDENT_JACOBIAN_CHECKS.csv',ind);np.savez_compressed(R/'08_mesh_quality/FAILED_ELEMENT_EVIDENCE.npz',element_indices=bad,original_node_ids=tet[bad],original_element_coordinates=xx[tet[bad]],original_quality=quality[bad],original_minJ=minJ[bad],Jacobian_samples=samples)
 write(R/'08_mesh_quality/INDEPENDENT_FAILURE_VERIFICATION.json',dict(UTC=now(),passed=True,confirmed_failed_mesh=True,independently_checked_elements=len(checkids),samples_each=73,invalid_minSICN_elements=int((quality<.02).sum()),negative_J_elements=int((minJ<0).sum()),zero_J_elements=int((minJ==0).sum()),maximum_minJ_disagreement_mm3=max(z['max_minJ_disagreement_mm3'] for z in ind),diagnosis='Same-element linear midsides compared solely to isolate high-order curvature placement kinematics. No repaired candidate or optimization produced. No native solve.',new_meshes=0,new_solves=0))
 # Complete identity/topology/datum-only audits for all3; no new full geometry candidates after stop.
 fits=[];thick=[];residuals=[];sourceaudit=[];planes=[]
 for row in rows(R/'R8E10_PILOT_QUEUE.csv'):
  s=row['source_id'];g=E3/'02_geometry/single'/s;xyz=np.load(g/'xyz.npy');tri=np.load(g/'triangles.npy');ids=np.load(g/'source_ids.npy');area=np.load(g/'area.npy');old=read(E9/'02_inventory/FRONT_DATUM_AND_BVP_DRYRUN.json')[s];bounds=old['domain_bounds'];d,mask=front_parent_datum(xyz,area,bounds);assert d['screen_pass'];assert max(abs(d[k]-old[k]) for k in ['intercept_Z_mm','slope_X','slope_Y','parent_RMS_mm','parent_P95_abs_mm'])<1e-12
  edges=np.sort(np.vstack([tri[:,[0,1]],tri[:,[1,2]],tri[:,[2,0]]]),axis=1);ed,count=np.unique(edges,axis=0,return_counts=True);graph=coo_matrix((np.ones(len(ed)),(ed[:,0],ed[:,1])),shape=(len(xyz),len(xyz)));assert connected_components(graph,directed=False,return_labels=False)==1 and count.max()==2 and len(xyz)-len(ed)+len(tri)==1
  fit=dict(source_id=s,protocol_version=read(E9/'03_config/TARGET_STANDARD_PLANAR_V1.json')['version'],**d);fits.append(fit);thick.append(dict(source_id=s,protocol_version=fit['protocol_version'],nominal_thickness_mm=19,basis='DOCUMENTED_NOMINAL_E9_SOURCE_REGISTRY',independently_measured=False,verified=True));z=xyz[mask,2]-(d['intercept_Z_mm']+d['slope_X']*(xyz[mask,0]-d['origin_X_mm'])+d['slope_Y']*(xyz[mask,1]-d['origin_Y_mm']));residuals.append(dict(source_id=s,protocol_version=fit['protocol_version'],points=int(mask.sum()),area_weighted_RMS_mm=d['parent_RMS_mm'],area_weighted_P95_mm=d['parent_P95_abs_mm'],maximum_abs_mm=float(abs(z).max()),passed=True))
  norm=float(np.sqrt(1+d['slope_X']**2+d['slope_Y']**2));planes.append(dict(source_id=s,protocol_version=fit['protocol_version'],datum_Z_at_origin_mm=d['intercept_Z_mm'],origin_X_mm=d['origin_X_mm'],origin_Y_mm=d['origin_Y_mm'],slope_X=d['slope_X'],slope_Y=d['slope_Y'],rear_Z_at_origin_mm=d['intercept_Z_mm']-19*norm,vertical_offset_mm=19*norm,true_normal_thickness_mm=19,normal_X=-d['slope_X']/norm,normal_Y=-d['slope_Y']/norm,normal_Z=1/norm,definition_status='CONSTRUCTED_CAD' if s==sid else 'FRONT_METADATA_ONLY_NO_CAD_AFTER_STOP'))
  sourceaudit.append(dict(source_id=s,protocol_version=fit['protocol_version'],points=len(xyz),triangles=len(tri),complete_rectangular_graph=len(xyz)==1201*57,unique_source_ids=len(np.unique(ids)),source_graph_Euler=1,boundary_edges=int((count==1).sum()),nonmanifold_edges=0,connected_components=1,parent_pass=True,source_XYZ_SHA256=sha(g/'xyz.npy'),source_triangles_SHA256=sha(g/'triangles.npy'),source_ids_SHA256=sha(g/'source_ids.npy'),physical_independence='UNCERTIFIED'))
 table(R/'PARENT_DATUM_FITS.csv',fits);table(R/'PARENT_DATUM_RESIDUALS.csv',residuals);table(R/'NOMINAL_THICKNESS_REGISTRY.csv',thick);table(R/'STANDARDIZED_REAR_PLANES.csv',planes);table(R/'02_source_geometry/SOURCE_TOPOLOGY_AUDIT.csv',sourceaudit)
 write(R/'17_reproducibility/IMPLEMENTATION_RECOVERY_LOG.json',dict(recoveries=[dict(stage='preCAD topology assertion',cause='Canonical T0 stores all lower triangles then all upper triangles; initial checker incorrectly assumed interleaving',resolution='Correct checker to exact historical ordering; no source mutation or generation had occurred'),dict(stage='preCAD datum consistency',cause='Initial checker inferred float32 extents rather than frozen full-design float64 bounds',resolution='Use authoritative original design bounds as E9; no CAD generated'),dict(stage='CAD audit only',cause='Spline clamps outside finite bounds while BRep evaluates analytic extension at float32-rounded boundary',resolution='Check representation identity inside bounds; preserve full-source sameXY metrics and originalXYZ. ExistingSTEP audited without regeneration; extrapolation max6.1035e-6mm disclosed'),dict(stage='mesh audit only',cause='NumPy2 batched solve RHS needed explicit trailing axis in supplementary closest-patch diagnostic',resolution='Correct RHS shape and rerun audit on identical existing mesh bytes; no remeshing')],criteria_relaxed=False,actual_CAD_generations=1,actual_full_FE_mesh_generations=1,native_SOLVEs=0))
 print('NEGATIVE_J_CONFIRMED',answer,flush=True)
if __name__=='__main__':main()
